pub fn compose(a: char, b: char) -> Option<char> {
    let k = ((a as u64) << 32) | (b as u64);
    COMPOSITION
        .binary_search_by_key(&k, |r| r.0)
        .ok()
        .and_then(|i| char::from_u32(COMPOSITION[i].1))
}
pub fn combining_class(c: char) -> u8 {
    let cp = c as u32;
    let i = COMBINING.partition_point(|r| r.0 <= cp);
    if i > 0 && cp <= COMBINING[i - 1].1 {
        COMBINING[i - 1].2
    } else {
        0
    }
}
pub fn mirrored(c: char) -> Option<char> {
    MIRROR
        .binary_search_by_key(&(c as u32), |r| r.0)
        .ok()
        .and_then(|i| char::from_u32(MIRROR[i].1))
}
